import { get, money, type Account, type Invoice, type Me } from '../lib/api';
import { PayButton } from './pay-button';

export const dynamic = 'force-dynamic';

const BANNER: Record<string, string | undefined> = {
  past_due: 'Your payment method failed. Update it to keep sending invoices.',
  suspended: 'This account is suspended. Invoices cannot be sent or paid.',
};

export default async function InvoicesPage() {
  const [account, invoices, me] = await Promise.all([get<Account>('/v1/account'), get<Invoice[]>('/v1/invoices'), get<Me>('/v1/me')]);
  const banner = BANNER[account.status];
  return (
    <>
      <h1 data-testid="account-name">{account.name}</h1>
      <p className="muted" data-testid="plan">
        {account.plan} plan · {account.seats} seats
      </p>
      {banner && (
        <div role="status" className={`banner banner--${account.status}`} data-testid="banner">
          {banner}
        </div>
      )}
      <h2>Invoices</h2>
      {invoices.length === 0 ? (
        <p data-testid="empty">No invoices yet. Create your first invoice to get paid.</p>
      ) : (
        <table className="table" data-testid="invoices">
          <tbody>
            {invoices.map((inv) => (
              <tr key={inv.id}>
                <td>{inv.customer}</td>
                <td>{inv.due}</td>
                <td className={`status status--${inv.status}`}>{inv.status}</td>
                <td className="num">{money(inv.amount)}</td>
                <td>{inv.status !== 'paid' && me.role === 'owner' && account.status !== 'suspended' ? <PayButton id={inv.id} /> : null}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  );
}
'use client';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { API } from '../lib/api';

/** A client-side write: the browser calls the API directly, then refreshes server components. */
export function PayButton({ id }: { id: string }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  return (
    <button
      className="btn"
      disabled={busy}
      onClick={async () => {
        setBusy(true);
        await fetch(`${API}/v1/invoices/${id}/pay`, { method: 'POST' });
        router.refresh();
        setBusy(false);
      }}
    >
      Mark paid
    </button>
  );
}
import { get, type Account, type Me } from '../../lib/api';

export const dynamic = 'force-dynamic';

export default async function Settings() {
  const [me, account] = await Promise.all([get<Me>('/v1/me'), get<Account>('/v1/account')]);
  return (
    <>
      <h1>Settings</h1>
      <p data-testid="settings-role">{me.role === 'owner' ? `You can change billing for ${account.name}.` : 'Only the account owner can change billing.'}</p>
    </>
  );
}
'use client';
import { useCallback, type ReactNode } from 'react';
import { useRouter } from 'next/navigation';
import { StagecraftRoot } from '@stagecraft/react';

export function Providers({ children }: { children: ReactNode }) {
  const router = useRouter();
  // Server components hold the data: re-fetch them when the prototype state changes.
  const refresh = useCallback(() => router.refresh(), [router]);
  return <StagecraftRoot onDataChange={refresh}>{children}</StagecraftRoot>;
}
import type { ReactNode } from 'react';
import Link from 'next/link';
import { Providers } from './providers';
import { get, type Me } from '../lib/api';
import './globals.css';

export const metadata = { title: 'Acme Billing' };

export default async function RootLayout({ children }: { children: ReactNode }) {
  const me = await get<Me>('/v1/me');
  return (
    <html lang="en">
      <body>
        <nav className="nav">
          <strong>Acme Billing</strong>
          <Link href="/">Invoices</Link>
          <Link href="/settings">Settings</Link>
          <span className="spacer" />
          <span data-testid="me">
            {me.name} · {me.role}
          </span>
        </nav>
        <main className="main">
          <Providers>{children}</Providers>
        </main>
      </body>
    </html>
  );
}
// The billing API lives on another host. In production this is a real service.
export const API = 'https://api.acme-billing.example';

export interface Account { name: string; plan: string; status: 'active' | 'past_due' | 'suspended'; seats: number }
export interface Invoice { id: string; customer: string; amount: number; status: 'open' | 'paid' | 'overdue'; due: string }
export interface Me { id: string; name: string; role: 'owner' | 'viewer' }

/** Server-side data access. Runs in React Server Components. */
export async function get<T>(path: string): Promise<T> {
  const res = await fetch(API + path, { cache: 'no-store' });
  if (!res.ok) throw new Error(`${path} failed with ${res.status}`);
  return res.json() as Promise<T>;
}

export const money = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));

/** @type {import('next').NextConfig} */
export default {
  // Monorepo only: workspace packages live outside this folder.
  turbopack: { root: "/home/user/build-mode" },
  transpilePackages: ['@stagecraft/react'],
};

