import { defineHandlers } from '@stagecraft/core';
import type { DB } from './seed';

// Keys are "METHOD /path/:param". Mutate ctx.db to persist writes for the session.
// Served for the billing API origin listed in stagecraft.config.ts (apiOrigins).
export const handlers = defineHandlers<DB>({
  'GET /v1/me': ({ db, persona, reply }) => {
    const u = db.users.find((x) => x.id === persona.userId);
    if (!u) return reply(401, { error: 'Not signed in' });
    return { id: u.id, name: u.name, role: u.role };
  },

  'GET /v1/account': ({ db }) => {
    const { name, plan, status, seats } = db.account;
    return { name, plan, status, seats };
  },

  'GET /v1/invoices': ({ db }) => db.invoices,

  'POST /v1/invoices/:id/pay': ({ db, params, persona, reply }) => {
    const me = db.users.find((x) => x.id === persona.userId);
    if (me?.role !== 'owner') return reply(403, { error: 'Only the account owner can mark invoices paid' });
    if (db.account.status === 'suspended') return reply(409, { error: 'Account is suspended' });
    const inv = db.invoices.find((i) => i.id === params.id);
    if (!inv) return reply(404, { error: 'Not found' });
    inv.status = 'paid';
    return inv;
  },
});

